1	package consensus
2	
3	import (
4		"crypto/sha256"
5		"encoding/binary"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"os"
11		"path/filepath"
12		"sort"
13		"sync"
14	)
15	
16	// Config 是节点初始化时固定的配置。
17	type Config struct {
18		// Seed 决定每轮提议者的种子，任意非空字节。
19		Seed []byte
20		// Validators 固定、非空、无重复的验证者公钥名单（Ed25519 32 字节公钥）。
21		Validators [][]byte
22		// MaxTxsPerBlock 单块交易上限，必须为正整数。
23		MaxTxsPerBlock uint64
24	}
25	
26	// entryStatus 与对外的 TxStatus 取值一致，额外区分内部存储。
27	type entryStatus string
28	
29	const (
30		stQueued    entryStatus = "queued"
31		stProposed  entryStatus = "proposed"
32		stConfirmed entryStatus = "confirmed"
33		stReplaced  entryStatus = "replaced"
34		stExpired   entryStatus = "expired"
35	)
36	
37	type poolEntry struct {
38		Tx         *Transaction `json:"tx"`
39		Status     entryStatus  `json:"status"`
40		ReplacedBy string       `json:"replaced_by,omitempty"`
41	}
42	
43	type confirmedRef struct {
44		Height uint64 `json:"height"`
45		Block  string `json:"block_id"`
46	}
47	
48	type proposalState struct {
49		Round   uint64   `json:"round"`
50		TxIDs   []string `json:"tx_ids"`
51		BlockID string   `json:"block_id"`
52		Votes   []string `json:"votes"` // 已投票验证者公钥的十六进制，按字典序保存
53	}
54	
55	// candidateState 是一轮中的一个候选块。同一轮多个候选共享相同的轮次、
56	// 下一高度与前块标识，仅交易顺序可以不同。
57	type candidateState struct {
58		TxIDs   []string `json:"tx_ids"`
59		BlockID string   `json:"block_id"`
60		Votes   []string `json:"votes"` // 已投票验证者公钥的十六进制，按字典序保存
61		// Local 标记该候选是否为本节点 Propose 产生的本地提议。
62		Local bool `json:"local"`
63		// Decided 表示该候选已决出：胜出确认或在轮次结束时落选。
64		Decided bool `json:"decided"`
65		// Winner 仅在 Decided 时有意义：true 为胜出，false 为落选。
66		Winner bool `json:"winner,omitempty"`
67	}
68	
69	// roundState 记录一个轮次的全部候选与结果。轮次决出后仍保留用于历史查询。
70	type roundState struct {
71		Round        uint64                     `json:"round"`
72		Height       uint64                     `json:"height"`     // 该轮候选使用的下一高度
73		PreviousID   string                     `json:"prev_id"`    // 该轮候选接在其后的最新确认块
74		Candidates   map[string]*candidateState `json:"candidates"` // 区块标识 -> 候选
75		LocalBlockID string                     `json:"local_block_id"`
76		// Ended 本轮已决出：候选确认或被 EndRound 主动结束。
77		Ended bool `json:"ended"`
78		// EndedByConfirm 决出方式：true 为投票确认，false 为主动结束（全部落选）。
79		EndedByConfirm bool `json:"ended_by_confirm,omitempty"`
80		// DetailMissing 表示该轮候选详情由旧版本状态迁移而来、并未保存，
81		// 查询时明确显示无记录；确认块本身不受影响。
82		DetailMissing bool `json:"detail_missing,omitempty"`
83	}
84	
85	// state 是持久化到磁盘的完整节点状态。
86	type state struct {
87		Version    int                          `json:"version"`
88		Seed       []byte                       `json:"seed"`
89		Validators [][]byte                     `json:"validators"`
90		MaxTxs     uint64                       `json:"max_txs_per_block"`
91		Round      uint64                       `json:"round"`
92		LastBlock  string                       `json:"last_block_id"`
93		Accounts   map[string]uint64            `json:"accounts"` // 发送者十六进制公钥 -> 已确认序号
94		Pool       map[string]map[uint64]string `json:"pool"`     // 发送者 -> 序号 -> 交易标识（含已提议交易）
95		Entries    map[string]*poolEntry        `json:"entries"`
96		Confirmed  map[string]confirmedRef      `json:"confirmed"`
97		Blocks     []Block                      `json:"blocks"`
98		// Rounds 按轮次保存候选与结果，含已决出的历史轮次。
99		Rounds map[uint64]*roundState `json:"rounds,omitempty"`
100		// Proposal 仅用于读取版本 1 的旧状态文件；版本 2 起一律由 Rounds 表达。
101		Proposal *proposalState `json:"proposal,omitempty"`
102	}
103	
104	const stateVersion = 2
105	const stateFileName = "state.json"
106	
107	// Node 是一个本地共识节点。一个进程内可串行调用其方法。
108	type Node struct {
109		dir string
110		mu  sync.Mutex
111		st  *state
112		// injectSaveErr 仅供同包测试使用：非 nil 时 save 直接失败，模拟写入错误。
113		injectSaveErr error
114	}
115	
116	func validateConfig(cfg Config) error {
117		if len(cfg.Seed) == 0 {
118			return errors.New("seed must be non-empty")
119		}
120		if len(cfg.Validators) == 0 {
121			return errors.New("validators must be non-empty")
122		}
123		if cfg.MaxTxsPerBlock == 0 {
124			return errors.New("max txs per block must be a positive integer")
125		}
126		seen := make(map[string]struct{}, len(cfg.Validators))
127		for i, v := range cfg.Validators {
128			if len(v) == 0 {
129				return fmt.Errorf("validator %d is empty", i)
130			}
131			key := fmt.Sprintf("%x", v)
132			if _, ok := seen[key]; ok {
133				return fmt.Errorf("duplicate validator %s", key)
134			}
135			seen[key] = struct{}{}
136		}
137		return nil
138	}
139	
140	// New 在 dir 中初始化一个新节点。目录不存在会创建；若已有状态文件则报错，
141	// 以免覆盖既有链历史，请改用 Open。
142	func New(dir string, cfg Config) (*Node, error) {
143		if err := validateConfig(cfg); err != nil {
144			return nil, err
145		}
146		if err := os.MkdirAll(dir, 0o755); err != nil {
147			return nil, err
148		}
149		path := filepath.Join(dir, stateFileName)
150		if _, err := os.Stat(path); err == nil {
151			return nil, fmt.Errorf("state file already exists at %s; use Open to resume", path)
152		}
153		validators := make([][]byte, len(cfg.Validators))
154		for i, v := range cfg.Validators {
155			validators[i] = append([]byte(nil), v...)
156		}
157		st := &state{
158			Version:    stateVersion,
159			Seed:       append([]byte(nil), cfg.Seed...),
160			Validators: validators,
161			MaxTxs:     cfg.MaxTxsPerBlock,
162			Round:      1, // 轮次从 1 开始
163			Accounts:   map[string]uint64{},
164			Pool:       map[string]map[uint64]string{},
165			Entries:    map[string]*poolEntry{},
166			Confirmed:  map[string]confirmedRef{},
167			Blocks:     []Block{},
168			Rounds:     map[uint64]*roundState{},
169		}
170		n := &Node{dir: dir, st: st}
171		if err := n.save(st); err != nil {
172			return nil, err
173		}
174		return n, nil
175	}
176	
177	// Open 从 dir 恢复此前由 New 创建的节点，恢复轮次、交易池、未决候选、
178	// 每人已投的选择、票数与确认历史。版本 1 的旧状态目录仍可打开。
179	func Open(dir string) (*Node, error) {
180		path := filepath.Join(dir, stateFileName)
181		raw, err := os.ReadFile(path)
182		if err != nil {
183			return nil, err
184		}
185		st := &state{}
186		if err := json.Unmarshal(raw, st); err != nil {
187			return nil, fmt.Errorf("corrupt state file %s: %w", path, err)
188		}
189		if st.Version != 1 && st.Version != stateVersion {
190			return nil, fmt.Errorf("unsupported state version %d", st.Version)
191		}
192		if st.Round == 0 {
193			st.Round = 1
194		}
195		if st.Rounds == nil {
196			st.Rounds = map[uint64]*roundState{}
197		}
198		if st.Version == 1 {
199			migrateV1(st)
200		}
201		return &Node{dir: dir, st: st}, nil
202	}
203	
204	// migrateV1 把版本 1 状态迁移到当前版本：
205	// 未决提议与其票数恢复为当前轮次的本地候选；旧版本未保存候选详情，
206	// 历史轮次一律标记为无记录（其中确认轮仍可通过确认块查询），已有确认块不变。
207	func migrateV1(st *state) {
208		st.Version = stateVersion
209		// 1..Round-1 中每个已跳过的轮次都没有保存候选详情；
210		// 无确认块即说明该轮经 EndRound 结束、未确认。
211		for r := uint64(1); r < st.Round; r++ {
212			if _, ok := st.Rounds[r]; ok {
213				continue
214			}
215			st.Rounds[r] = &roundState{
216				Round:         r,
217				Candidates:    map[string]*candidateState{},
218				Ended:         true,
219				DetailMissing: true,
220			}
221		}
222		for _, b := range st.Blocks {
223			st.Rounds[b.Round] = &roundState{
224				Round:          b.Round,
225				Height:         b.Height,
226				PreviousID:     b.PreviousID,
227				Candidates:     map[string]*candidateState{},
228				LocalBlockID:   b.ID,
229				Ended:          true,
230				EndedByConfirm: true,
231				DetailMissing:  true,
232			}
233		}
234		if st.Proposal != nil {
235			p := st.Proposal
236			rs := &roundState{
237				Round:      p.Round,
238				Height:     uint64(len(st.Blocks)) + 1,
239				PreviousID: st.LastBlock,
240				Candidates: map[string]*candidateState{
241					p.BlockID: &candidateState{
242						TxIDs:   append([]string{}, p.TxIDs...),
243						BlockID: p.BlockID,
244						Votes:   append([]string{}, p.Votes...),
245						Local:   true,
246					},
247				},
248				LocalBlockID: p.BlockID,
249			}
250			// 被未决提议引用的交易在版本 1 中已标记为 proposed，语义不变，原样保留。
251			st.Rounds[p.Round] = rs
252		}
253		st.Proposal = nil
254	}
255	
256	// ConfigSnapshot 返回节点的固定配置副本。
257	type ConfigSnapshot struct {
258		Seed           []byte
259		Validators     [][]byte
260		MaxTxsPerBlock uint64
261	}
262	
263	// Config 返回初始化时的配置副本。
264	func (n *Node) Config() ConfigSnapshot {
265		n.mu.Lock()
266		defer n.mu.Unlock()
267		vals := make([][]byte, len(n.st.Validators))
268		for i, v := range n.st.Validators {
269			vals[i] = append([]byte(nil), v...)
270		}
271		return ConfigSnapshot{
272			Seed:           append([]byte(nil), n.st.Seed...),
273			Validators:     vals,
274			MaxTxsPerBlock: n.st.MaxTxs,
275		}
276	}
277	
278	// CurrentRound 返回当前轮次，首轮为 1。
279	func (n *Node) CurrentRound() uint64 {
280		n.mu.Lock()
281		defer n.mu.Unlock()
282		return n.st.Round
283	}
284	
285	// proposerAt 是确定性的轮次提议者选择：
286	// 对 seed || round(大端 8 字节) 取 SHA-256，结果对名单人数取模。
287	// 种子、名单顺序与轮次相同时，提议者必然相同。
288	func proposerAt(seed []byte, validators [][]byte, round uint64) []byte {
289		var buf [8]byte
290		binary.BigEndian.PutUint64(buf[:], round)
291		h := sha256.New()
292		h.Write(seed)
293		h.Write(buf[:])
294		sum := h.Sum(nil)
295		idx := binary.BigEndian.Uint64(sum[:8]) % uint64(len(validators))
296		return validators[idx]
297	}
298	
299	// ProposerFor 返回指定轮次的提议者公钥。
