311	// SubmitResult 是交易提交结果。
312	type SubmitResult struct {
313		// TxID 被接受交易的标识。
314		TxID string
315		// ReplacedID 若本次提交替换了旧交易，为旧交易标识；否则为空。
316		ReplacedID string
317	}
318	
319	// Submit 校验并接收一笔交易进入交易池。
320	// 拒绝时返回 *RejectError，可通过其 Reason 取得具体原因。
321	func (n *Node) Submit(tx *Transaction) (*SubmitResult, error) {
322		if tx == nil {
323			return nil, errors.New("nil transaction")
324		}
325		n.mu.Lock()
326		defer n.mu.Unlock()
327	
328		cur := n.st
329		if tx.Sequence == 0 {
330			return nil, reject("sequence-must-be-positive", "sequence must be a positive integer")
331		}
332		if !tx.Verify() {
333			return nil, reject(ReasonBadSignature, "signature verification failed for sender %x", tx.Sender)
334		}
335		id := tx.ID()
336		// 同一标识的交易再次提交，一律视为重复（即使此前已确认、被替换或过期）。
337		if _, ok := cur.Entries[id]; ok {
338			return nil, reject(ReasonDuplicate, "transaction %s already exists", id)
339		}
340		if cur.Round >= tx.Expiry {
341			return nil, reject(ReasonExpired, "expiry round %d is not greater than current round %d", tx.Expiry, cur.Round)
342		}
343		sender := tx.SenderHex()
344		if confirmed := cur.Accounts[sender]; tx.Sequence <= confirmed {
345			return nil, reject(ReasonOldSequence, "sequence %d is not greater than confirmed sequence %d", tx.Sequence, confirmed)
346		}
347		seqs := cur.Pool[sender]
348		if seqs != nil {
349			if oldID, ok := seqs[tx.Sequence]; ok {
350				old := cur.Entries[oldID]
351				if old.Status == stProposed {
352					return nil, reject(ReasonProposalLocked, "sequence %d is referenced by a pending candidate and cannot be replaced", tx.Sequence)
353				}
354				if tx.Fee <= old.Tx.Fee {
355					return nil, reject(ReasonLowFee, "new fee %d is not strictly higher than existing fee %d", tx.Fee, old.Tx.Fee)
356				}
357			}
358		}
359	
360		// 校验通过后在副本上修改，落盘成功才替换内存，失败时确认前状态保持不变。
361		st := cur.clone()
362		result := &SubmitResult{TxID: id}
363		if oldID, ok := st.Pool[sender][tx.Sequence]; ok {
364			old := st.Entries[oldID]
365			old.Status = stReplaced
366			old.ReplacedBy = id
367			result.ReplacedID = oldID
368		}
369	
370		txCopy := *tx
371		txCopy.Sender = append([]byte(nil), tx.Sender...)
372		txCopy.Content = append([]byte(nil), tx.Content...)
373		txCopy.Signature = append([]byte(nil), tx.Signature...)
374		st.Entries[id] = &poolEntry{Tx: &txCopy, Status: stQueued}
375		if st.Pool[sender] == nil {
376			st.Pool[sender] = map[uint64]string{}
377		}
378		st.Pool[sender][tx.Sequence] = id
379	
380		if err := n.save(st); err != nil {
381			return nil, err
382		}
383		n.st = st
384		return result, nil
385	}
