387	// 额外拒绝原因。
388	const (
389		// ReasonProposalLocked 同发送者同序号交易已被未决候选引用，禁止替换。
390		ReasonProposalLocked = "tx-in-proposal"
391		// ReasonUnknownTx 查询的交易标识不存在。
392		ReasonUnknownTx = "unknown-transaction"
393		// ReasonUnknownBlock 查询的区块高度不存在。
394		ReasonUnknownBlock = "unknown-block"
395		// ReasonTxNotInPool 候选引用了已退出交易池的交易（已确认、被替换或已过期）。
396		ReasonTxNotInPool = "tx-not-in-pool"
397		// ReasonDuplicateInList 候选列表中同一交易出现多次。
398		ReasonDuplicateInList = "duplicate-in-list"
399		// ReasonTooManyTxs 候选包含的交易超过单块上限。
400		ReasonTooManyTxs = "too-many-transactions"
401		// ReasonSequenceGap 候选中某账户的序号未从已确认序号加一开始连续递增。
402		ReasonSequenceGap = "sequence-not-consecutive"
403	)
