419	// Proposal 返回当前轮次本地提议；尚未提议时第二个返回值为 false。
420	// 重复调用、登记其他候选均不改变本地提议。
421	func (n *Node) Proposal() (ProposalView, bool) {
422		n.mu.Lock()
423		defer n.mu.Unlock()
424		rs := n.st.currentRoundState()
425		if rs == nil || rs.LocalBlockID == "" {
426			return ProposalView{}, false
427		}
428		return proposalViewOf(rs.Round, rs.Candidates[rs.LocalBlockID]), true
429	}
