431	func proposalViewOf(round uint64, c *candidateState) ProposalView {
432		ids := append([]string(nil), c.TxIDs...)
433		return ProposalView{Round: round, BlockID: c.BlockID, TxIDs: ids, Empty: len(ids) == 0}
434	}
