436	// Propose 返回当前轮次唯一的本地提议；重复请求返回同一提议。
437	// 提议生成后即冻结：此后新提交的交易或新登记的候选都不改变该提议，
438	// 提议中的交易禁止替换。其他候选用 RegisterCandidate 另行登记。
439	func (n *Node) Propose() (ProposalView, error) {
440		n.mu.Lock()
441		defer n.mu.Unlock()
442		if rs := n.st.currentRoundState(); rs != nil && rs.LocalBlockID != "" {
443			return proposalViewOf(rs.Round, rs.Candidates[rs.LocalBlockID]), nil
444		}
445	
446		st := n.st.clone()
447		rs := st.Rounds[st.Round]
448		if rs == nil {
449			rs = &roundState{
450				Round:      st.Round,
451				Height:     uint64(len(st.Blocks)) + 1,
452				PreviousID: st.LastBlock,
453				Candidates: map[string]*candidateState{},
454			}
455			st.Rounds[st.Round] = rs
456		}
457		txIDs := st.selectTransactions()
458		blockID := BlockID(st.Round, rs.Height, rs.PreviousID, txIDs)
459		c := &candidateState{
460			TxIDs:   txIDs,
461			BlockID: blockID,
462			Votes:   []string{},
463			Local:   true,
464		}
465		rs.Candidates[blockID] = c
466		rs.LocalBlockID = blockID
467		for _, id := range txIDs {
468			st.Entries[id].Status = stProposed
469		}
470		if err := n.save(st); err != nil {
471			return ProposalView{}, err
472		}
473		n.st = st
474		return proposalViewOf(rs.Round, c), nil
475	}
