501	// RegisterCandidate 在当前轮次本地提议已产生且尚未确认时，按给定交易顺序登记一个
502	// 竞争候选，与本地提议一起参与投票。候选使用当前轮次与下一高度，接在最新确认块之后。
503	//
504	// 候选只能包含当前池内排队或已提议的交易，数量不得超过单块上限，允许空块；
505	// 列表不能重复交易；每个账户在列表中的序号必须从该账户已确认序号加一开始连续递增，
506	// 不同账户之间的顺序由调用者决定。相同列表重复登记返回同一候选并保留已有票数。
507	//
508	// 未产生本地提议、轮次不是当前轮次、引用未知或已退出池的交易、超过上限或序号
509	// 不连续时登记失败并返回带具体 Reason 的 *RejectError，节点状态不变。
510	func (n *Node) RegisterCandidate(round uint64, txIDs []string) (*RegisterResult, error) {
511		n.mu.Lock()
512		defer n.mu.Unlock()
513	
514		rs := n.st.currentRoundState()
515		// 轮次优先判定：非当前轮次不能登记，即使当前轮次尚未产生本地提议。
516		if round != n.st.Round {
517			return nil, reject(ReasonWrongRound, "candidate round %d does not match current round %d", round, n.st.Round)
518		}
519		if rs == nil || rs.LocalBlockID == "" {
520			return nil, reject(ReasonNoProposal, "round %d has no local proposal yet", n.st.Round)
521		}
522	
523		ids := append([]string{}, txIDs...)
524		if uint64(len(ids)) > n.st.MaxTxs {
525			return nil, reject(ReasonTooManyTxs, "candidate contains %d transactions, max per block is %d", len(ids), n.st.MaxTxs)
526		}
527		// 列表内不得重复交易。
528		seen := make(map[string]struct{}, len(ids))
529		for _, id := range ids {
530			if _, dup := seen[id]; dup {
531				return nil, reject(ReasonDuplicateInList, "transaction %s appears more than once in candidate list", id)
532			}
533			seen[id] = struct{}{}
534			e, ok := n.st.Entries[id]
535			if !ok {
536				return nil, reject(ReasonUnknownTx, "transaction %s not found", id)
537			}
538			// 必须仍在池中（排队或已被某未决候选引用）；已确认、被替换、已过期均已退出池。
539			if e.Status != stQueued && e.Status != stProposed {
540				return nil, reject(ReasonTxNotInPool, "transaction %s is not queued or proposed (status %s)", id, e.Status)
541			}
542			if !inPool(n.st, e.Tx.SenderHex(), e.Tx.Sequence, id) {
543				return nil, reject(ReasonTxNotInPool, "transaction %s has left the pool", id)
544			}
545		}
546		// 每个账户的序号必须从已确认序号加一开始连续递增。
547		seqsBySender := map[string][]uint64{}
548		for _, id := range ids {
549			e := n.st.Entries[id]
550			sender := e.Tx.SenderHex()
551			seqsBySender[sender] = append(seqsBySender[sender], e.Tx.Sequence)
552		}
553		senders := make([]string, 0, len(seqsBySender))
554		for sender := range seqsBySender {
555			senders = append(senders, sender)
556		}
557		sort.Strings(senders)
558		for _, sender := range senders {
559			seqs := seqsBySender[sender]
560			want := n.st.Accounts[sender] + 1
561			for i, seq := range seqs {
562				if seq != want {
563					return nil, reject(ReasonSequenceGap,
564						"sender %s candidate sequence at position %d is %d, want %d (must be consecutive starting at confirmed sequence + 1)",
565						sender, i, seq, want)
566				}
567				want++
568			}
569		}
570	
571		blockID := BlockID(rs.Round, rs.Height, rs.PreviousID, ids)
572		if existing, ok := rs.Candidates[blockID]; ok {
573			// 相同列表重复登记：返回同一候选，保留已有票数，节点状态不变。
574			return &RegisterResult{BlockID: existing.BlockID, Existing: true}, nil
575		}
576	
577		st := n.st.clone()
578		rs2 := st.Rounds[st.Round]
579		rs2.Candidates[blockID] = &candidateState{
580			TxIDs:   ids,
581			BlockID: blockID,
582			Votes:   []string{},
583		}
584		for _, id := range ids {
585			if st.Entries[id].Status == stQueued {
586				st.Entries[id].Status = stProposed
587			}
588		}
589		if err := n.save(st); err != nil {
590			return nil, err
591		}
592		n.st = st
593		return &RegisterResult{BlockID: blockID}, nil
594	}
595	
596	// inPool 判断标识 id 是否仍是池中某账户某序号的当前交易。
597	func inPool(st *state, sender string, seq uint64, id string) bool {
598		cur, ok := st.Pool[sender][seq]
599		return ok && cur == id
600	}
601	
602	// selectTransactions 执行确定性打包：
603	// 每轮从各账户“下一条可确认”的交易中选费用最高者，费用相同按交易标识字典序；
604	// 选入某账户后才继续考虑其后续序号，直到达到上限或没有可选交易。
605	func (n *state) selectTransactions() []string {
606		var picked []string
607		// 每个账户在本次打包中下一个可考虑的序号。
608		next := map[string]uint64{}
609		for sender := range n.Pool {
610			next[sender] = n.Accounts[sender] + 1
611		}
612		for uint64(len(picked)) < n.MaxTxs {
613			var bestID string
614			var bestFee uint64
615			var bestSet bool
616			// 遍历发送者名单需确定序：按发送者十六进制定序，保证选择只取决于费用与标识。
617			senders := make([]string, 0, len(n.Pool))
618			for s := range n.Pool {
619				senders = append(senders, s)
620			}
621			sort.Strings(senders)
622			for _, sender := range senders {
623				id, ok := n.Pool[sender][next[sender]]
624				if !ok {
625					continue
626				}
627				e := n.Entries[id]
628				if e.Status != stQueued {
629					continue
630				}
631				if !bestSet || e.Tx.Fee > bestFee || (e.Tx.Fee == bestFee && id < bestID) {
632					bestID = id
633					bestFee = e.Tx.Fee
634					bestSet = true
635				}
636			}
637			if !bestSet {
638				break
639			}
640			picked = append(picked, bestID)
641			next[n.Entries[bestID].Tx.SenderHex()]++
642		}
643		if picked == nil {
644			picked = []string{}
645		}
646		return picked
647	}
