649	// VoteResult 是投票处理结果。
650	type VoteResult struct {
651		// Counted 本次投票是否新计入票数（重复投同一候选为 false）。
652		Counted bool
653		// Confirmed 本次投票是否令某候选立即确认。
654		Confirmed bool
655		// Block 确认时为新区块；否则为 nil。
656		Block *Block
657	}
