659	// Vote 处理验证者对当前轮次某已登记候选的投票。
660	// 每位验证者一轮内只能选择一个候选：重复投同一候选不增加票数但不报错；
661	// 改投其他候选明确拒绝（ReasonAlreadyVoted），原票保留。
662	// 票数严格超过名单人数三分之二时立即确认该候选，其他候选落选并进入下一轮。
663	// 名单外身份、错误轮次、未知区块标识返回带具体 Reason 的 *RejectError。
664	func (n *Node) Vote(validator []byte, round uint64, blockID string) (*VoteResult, error) {
665		n.mu.Lock()
666		defer n.mu.Unlock()
667	
668		key := fmt.Sprintf("%x", validator)
669		allowed := false
670		for _, v := range n.st.Validators {
671			if fmt.Sprintf("%x", v) == key {
672				allowed = true
673				break
674			}
675		}
676		if !allowed {
677			return nil, reject(ReasonNotValidator, "validator %s is not in the validator set", key)
678		}
679		rs := n.st.currentRoundState()
680		// 轮次优先判定：旧轮次投票不能影响新轮次，即使新轮次尚未产生本地提议。
681		if rs == nil || rs.LocalBlockID == "" {
682			if round != n.st.Round {
683				return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, n.st.Round)
684			}
685			return nil, reject(ReasonNoProposal, "round %d has no proposal", n.st.Round)
686		}
687		if round != rs.Round {
688			return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, rs.Round)
689		}
690		if _, ok := rs.Candidates[blockID]; !ok {
691			return nil, reject(ReasonWrongBlock, "block id %s is not a registered candidate in round %d", blockID, rs.Round)
692		}
693	
694		// 每位验证者一轮内只能选择一个候选。
695		for id, cand := range rs.Candidates {
696			for _, vk := range cand.Votes {
697				if vk == key {
698					if id == blockID {
699						return &VoteResult{Counted: false}, nil // 重复投同一候选不增票
700					}
701					return nil, reject(ReasonAlreadyVoted,
702						"validator %s already voted for candidate %s in round %d and cannot switch to %s", key, id, rs.Round, blockID)
703				}
704			}
705		}
706	
707		st := n.st.clone()
708		rs2 := st.Rounds[st.Round]
709		cand := rs2.Candidates[blockID]
710		cand.Votes = append(cand.Votes, key)
711		sort.Strings(cand.Votes)
712	
713		res := &VoteResult{Counted: true}
714		threshold := len(st.Validators) * 2 / 3
715		if len(cand.Votes) > threshold {
716			block := st.resolveRound(cand.BlockID, true)
717			res.Confirmed = true
718			res.Block = &block
719		}
720		if err := n.save(st); err != nil {
721			return nil, err
722		}
723		n.st = st
724		return res, nil
725	}
726	
727	// resolveRound 在内存状态上完整应用一轮的决出：
728	// confirm 为 true 时胜出候选按其交易顺序生成连续高度的确认块，随后胜出与落选
729	// 候选中引用的交易分别按规则处理（确认一次 / 回到排队），最后进入下一轮并使
730	// 到期交易失效。confirm 为 false（EndRound）时不生成确认块，所有候选引用的
731	// 交易全部回到排队。调用方随后通过一次原子保存落盘。
732	func (s *state) resolveRound(winnerID string, confirm bool) Block {
733		rs := s.Rounds[s.Round]
734		var block Block
735		winnerTx := map[string]struct{}{}
736		if confirm {
737			winner := rs.Candidates[winnerID]
738			height := uint64(len(s.Blocks)) + 1
739			block = Block{
740				Height:     height,
741				Round:      rs.Round,
742				ID:         winner.BlockID,
743				PreviousID: s.LastBlock,
744				TxIDs:      append([]string(nil), winner.TxIDs...),
745			}
746			if block.TxIDs == nil {
747				block.TxIDs = []string{}
748			}
749			for _, id := range block.TxIDs {
750				winnerTx[id] = struct{}{}
751				e := s.Entries[id]
752				sender := e.Tx.SenderHex()
753				// 候选校验保证序号从已确认序号加一起连续递增。
754				s.Accounts[sender] = e.Tx.Sequence
755				delete(s.Pool[sender], e.Tx.Sequence)
756				if len(s.Pool[sender]) == 0 {
757					delete(s.Pool, sender)
758				}
759				e.Status = stConfirmed
760				e.ReplacedBy = ""
761				s.Confirmed[id] = confirmedRef{Height: height, Block: block.ID}
762			}
763			s.Blocks = append(s.Blocks, block)
764			s.LastBlock = block.ID
765		}
766		// 标记全部候选的胜出/落选结果；只有未在胜出块中的交易才回到排队。
767		// 被多个候选共享的胜出交易只确认一次，落选候选不能再改变其状态。
768		for id, cand := range rs.Candidates {
769			cand.Decided = true
770			cand.Winner = confirm && id == winnerID
771			if !cand.Winner {
772				for _, txID := range cand.TxIDs {
773					if _, won := winnerTx[txID]; won {
774						continue
775					}
776					if e, ok := s.Entries[txID]; ok && e.Status == stProposed {
777						e.Status = stQueued
778					}
779				}
780			}
781		}
782		rs.Ended = true
783		rs.EndedByConfirm = confirm
784		s.Round++
785		s.expire()
786		return block
787	}
788	
789	// expire 使池内到期轮次不大于当前轮次的交易失效。轮次已决出，池中剩余的
790	// 均为排队交易（落选候选独有或从未被引用）。
791	func (s *state) expire() {
792		for sender, seqs := range s.Pool {
793			for seq, id := range seqs {
794				e := s.Entries[id]
795				if e.Tx.Expiry <= s.Round {
796					e.Status = stExpired
797					delete(seqs, seq)
798				}
799			}
800			if len(seqs) == 0 {
801				delete(s.Pool, sender)
802			}
803		}
804	}
805	
806	// EndRound 主动结束当前未确认轮次：所有候选落选且不生成确认块，
807	// 候选中的交易按落选规则回到排队状态，随后进入下一轮并使到期交易失效。
808	// 旧轮次投票随候选结果一并保留在历史中，但不能影响新轮次。
809	func (n *Node) EndRound() (uint64, error) {
810		n.mu.Lock()
811		defer n.mu.Unlock()
812		st := n.st.clone()
813		rs := st.Rounds[st.Round]
814		if rs == nil {
815			// 本轮尚未产生本地提议：仍允许直接结束，空轮留作未确认结束记录。
816			rs = &roundState{
817				Round:      st.Round,
818				Height:     uint64(len(st.Blocks)) + 1,
819				PreviousID: st.LastBlock,
820				Candidates: map[string]*candidateState{},
821			}
822			st.Rounds[st.Round] = rs
823		}
824		st.resolveRound("", false)
825		if err := n.save(st); err != nil {
826			return 0, err
827		}
828		n.st = st
829		return st.Round, nil
830	}
831	
832	// Height 返回已确认区块数（最新高度）。
833	func (n *Node) Height() uint64 {
834		n.mu.Lock()
835		defer n.mu.Unlock()
836		return uint64(len(n.st.Blocks))
837	}
838	
839	// BlockAt 按连续高度查询确认块，高度从 1 开始。
840	func (n *Node) BlockAt(height uint64) (Block, error) {
841		n.mu.Lock()
842		defer n.mu.Unlock()
843		if height == 0 || height > uint64(len(n.st.Blocks)) {
844			return Block{}, reject(ReasonUnknownBlock, "block at height %d does not exist", height)
845		}
846		return n.st.Blocks[height-1], nil
847	}
848	
849	// LatestBlock 返回最新确认块；尚无确认块时第二返回值为 false。
850	func (n *Node) LatestBlock() (Block, bool) {
851		n.mu.Lock()
852		defer n.mu.Unlock()
853		if len(n.st.Blocks) == 0 {
854			return Block{}, false
855		}
856		return n.st.Blocks[len(n.st.Blocks)-1], true
857	}
858	
859	// 候选结果取值。
860	const (
861		// CandidatePending 候选尚未决出，仍可接受投票。
862		CandidatePending = "pending"
863		// CandidateWon 候选胜出，其交易已确认。
864		CandidateWon = "won"
865		// CandidateLost 轮次已结束且该候选落选。
866		CandidateLost = "lost"
867	)
868	
869	// RoundCandidates 是某一轮候选情况的只读视图。返回内容均为副本，
870	// 调用方修改切片或字节不会影响节点内部状态。
871	type RoundCandidates struct {
872		// Round 查询的轮次。
873		Round uint64
874		// Candidates 本轮全部候选，按区块标识字典序排列。
875		Candidates []CandidateView
876		// Unvoted 本轮尚未投票的验证者公钥，按公钥字典序排列。
877		Unvoted [][]byte
878		// Ended 本轮是否已经决出（确认或主动结束）。
879		Ended bool
880		// UnconfirmedEnd 为 true 表示本轮由 EndRound 主动结束、未产生确认块。
881		UnconfirmedEnd bool
882		// HasRecords 为 false 表示旧版本状态未保存该轮候选详情；
883		// 此时 Candidates 为空且不代表“该轮没有候选”。
884		HasRecords bool
885	}
886	
887	// Candidates 按轮次查看候选：列出每个候选的交易顺序、投票者（按公钥排序）
888	// 及未决/胜出/落选结果，并列出本轮尚未投票的验证者。旧轮记录保留可查；
889	// 轮次为 0 或尚未到达时返回 ReasonUnknownRound。
890	//
891	// 候选按区块标识排序，身份按公钥排序。主动结束的轮次 UnconfirmedEnd 为 true。
892	// 过去没有保存候选详情的旧轮 HasRecords 为 false。
893	func (n *Node) Candidates(round uint64) (*RoundCandidates, error) {
894		n.mu.Lock()
895		defer n.mu.Unlock()
896		// 轮次 0、尚未到达的未来轮次以及尚未产生本地提议的当前轮次均无记录。
897		// 历史轮次（含旧版本迁移轮）与未决当前轮一定有条目。
898		rs := n.st.Rounds[round]
899		if round == 0 || rs == nil {
900			return nil, reject(ReasonUnknownRound, "round %d does not exist (current round %d)", round, n.st.Round)
901		}
902		view := &RoundCandidates{
903			Round:          round,
904			Candidates:     []CandidateView{},
905			Unvoted:        [][]byte{},
906			Ended:          rs.Ended,
907			UnconfirmedEnd: rs.Ended && !rs.EndedByConfirm,
908			HasRecords:     !rs.DetailMissing,
909		}
910		if !rs.DetailMissing {
911			ids := make([]string, 0, len(rs.Candidates))
912			for id := range rs.Candidates {
913				ids = append(ids, id)
914			}
915			sort.Strings(ids)
916			voted := map[string]struct{}{}
917			for _, id := range ids {
918				c := rs.Candidates[id]
919				voters := make([][]byte, 0, len(c.Votes))
920				for _, vk := range c.Votes {
921					pub, err := hexDecode(vk)
922					if err != nil {
923						return nil, fmt.Errorf("corrupt voter key %q: %w", vk, err)
924					}
925					voters = append(voters, pub)
926					voted[vk] = struct{}{}
927				}
928				result := CandidatePending
929				if c.Decided {
930					if c.Winner {
931						result = CandidateWon
932					} else {
933						result = CandidateLost
934					}
935				}
936				view.Candidates = append(view.Candidates, CandidateView{
937					Round:   rs.Round,
938					BlockID: c.BlockID,
939					TxIDs:   append([]string(nil), c.TxIDs...),
940					Local:   c.Local,
941					Voters:  voters,
942					Result:  result,
943				})
944			}
945			valKeys := make([]string, 0, len(n.st.Validators))
946			for _, v := range n.st.Validators {
947				k := fmt.Sprintf("%x", v)
948				if _, ok := voted[k]; !ok {
949					valKeys = append(valKeys, k)
950				}
951			}
952			sort.Strings(valKeys)
953			for _, k := range valKeys {
954				pub, err := hexDecode(k)
955				if err != nil {
956					return nil, fmt.Errorf("corrupt validator key %q: %w", k, err)
957				}
958				view.Unvoted = append(view.Unvoted, pub)
959			}
960		}
961		return view, nil
962	}
963	
964	// hexDecode 解码十六进制公钥，非法输入返回错误。
965	func hexDecode(h string) ([]byte, error) {
966		return hex.DecodeString(h)
967	}
968	
969	// Tx 按交易标识查询其状态并关联区块或替代交易。
970	func (n *Node) Tx(id string) (*TxInfo, error) {
971		n.mu.Lock()
972		defer n.mu.Unlock()
973		if e, ok := n.st.Entries[id]; ok {
974			info := &TxInfo{
975				ID:         id,
976				Status:     TxStatus(e.Status),
977				Tx:         copyTx(e.Tx),
978				ReplacedBy: e.ReplacedBy,
979			}
980			if e.Status == stConfirmed {
981				if ref, ok := n.st.Confirmed[id]; ok {
982					info.BlockHeight = ref.Height
983					info.BlockID = ref.Block
984				}
985			}
986			return info, nil
987		}
988		return nil, reject(ReasonUnknownTx, "transaction %s not found", id)
989	}
990	
991	// Account 按发送者公钥查询已确认序号与全部待处理交易。
992	// 因序号缺口等待时 Gap 给出最早缺少的序号；
993	// 已提议交易显示等待投票，其余池内交易显示等待打包。
994	func (n *Node) Account(sender []byte) *AccountInfo {
995		n.mu.Lock()
996		defer n.mu.Unlock()
997		key := fmt.Sprintf("%x", sender)
998		info := &AccountInfo{
999			Sender:            key,
1000			ConfirmedSequence: n.st.Accounts[key],
1001			Pending:           []*TxInfo{},
1002		}
1003		seqs := n.st.Pool[key]
1004		if len(seqs) == 0 {
1005			return info
1006		}
1007		seqList := make([]uint64, 0, len(seqs))
1008		for seq := range seqs {
1009			seqList = append(seqList, seq)
1010		}
1011		sort.Slice(seqList, func(i, j int) bool { return seqList[i] < seqList[j] })
1012		expected := info.ConfirmedSequence + 1
1013		var gap uint64
1014		for _, seq := range seqList {
1015			if gap == 0 {
1016				if seq == expected {
1017					expected++
1018				} else if seq > expected {
1019					gap = expected
1020				}
1021			}
1022			id := seqs[seq]
1023			e := n.st.Entries[id]
1024			txInfo := &TxInfo{
1025				ID:     id,
1026				Status: TxStatus(e.Status),
1027				Tx:     copyTx(e.Tx),
1028			}
1029			if e.Status == stProposed {
1030				txInfo.Note = "waiting-vote"
1031			} else {
1032				txInfo.Note = "waiting-pack"
1033			}
1034			info.Pending = append(info.Pending, txInfo)
1035		}
1036		info.Gap = gap
1037		return info
1038	}
1039	
1040	func copyTx(tx *Transaction) *Transaction {
1041		if tx == nil {
1042			return nil
1043		}
1044		c := *tx
1045		c.Sender = append([]byte(nil), tx.Sender...)
1046		c.Content = append([]byte(nil), tx.Content...)
1047		c.Signature = append([]byte(nil), tx.Signature...)
1048		return &c
1049	}
1050

