1	package consensus
2	
3	import (
4		"crypto/ed25519"
5		"crypto/rand"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"testing"
11	)
12	
13	type testKey struct {
14		priv ed25519.PrivateKey
15		pub  ed25519.PublicKey
16	}
17	
18	func genKeys(t *testing.T, n int) []testKey {
19		t.Helper()
20		keys := make([]testKey, n)
21		for i := range keys {
22			pub, priv, err := ed25519.GenerateKey(rand.Reader)
23			if err != nil {
24				t.Fatal(err)
25			}
26			keys[i] = testKey{priv: priv, pub: pub}
27		}
28		return keys
29	}
30	
31	func newTestNode(t *testing.T, keys []testKey, maxTxs uint64) (*Node, string) {
32		t.Helper()
33		dir := t.TempDir()
34		vals := make([][]byte, len(keys))
35		for i, k := range keys {
36			vals[i] = k.pub
37		}
38		n, err := New(dir, Config{Seed: []byte("test-seed-v1"), Validators: vals, MaxTxsPerBlock: maxTxs})
39		if err != nil {
40			t.Fatal(err)
41		}
42		return n, dir
43	}
44	
45	func reason(err error) string {
46		var re *RejectError
47		if errors.As(err, &re) {
48			return re.Reason
49		}
50		return ""
51	}
52	
53	// 初始状态：轮次 1，账户确认序号 0，配置必须校验。
54	func TestInitialState(t *testing.T) {
55		keys := genKeys(t, 4)
56		n, _ := newTestNode(t, keys, 10)
57		if n.CurrentRound() != 1 {
58			t.Fatalf("initial round = %d, want 1", n.CurrentRound())
59		}
60		if n.Height() != 0 {
61			t.Fatalf("initial height = %d, want 0", n.Height())
