214	// 多候选投票：每人单选、重复不增票、改投拒绝且原票保留；非本地候选也能胜出确认。
215	func TestMultiCandidateVoting(t *testing.T) {
216		keys := genKeys(t, 4)
217		n, _ := newTestNode(t, keys, 10)
218	
219		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
220		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
221		n.Submit(a1)
222		n.Submit(b1)
223		local, _ := n.Propose() // 打包顺序：b1(5) 先、a1(1) 后。
224		// 竞争候选：与本地提议相反的顺序。
225		list := []string{a1.ID(), b1.ID()}
226		alt, err := n.RegisterCandidate(1, list)
227		if err != nil {
228			t.Fatal(err)
229		}
230		if alt.BlockID == local.BlockID || fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{b1.ID(), a1.ID()}) {
231			t.Fatalf("setup wrong: local=%v alt=%s", local.TxIDs, alt.BlockID)
232		}
233	
234		// 未知区块标识拒绝。
235		if _, err := n.Vote(keys[0].pub, 1, "deadbeef"); reason(err) != ReasonWrongBlock {
236			t.Fatalf("got %v, want %s", err, ReasonWrongBlock)
237		}
238	
239		// keys[0] 投本地；重复不增票；改投明确拒绝且原票保留。
240		if res, err := n.Vote(keys[0].pub, 1, local.BlockID); err != nil || !res.Counted {
241			t.Fatalf("first vote: %+v %v", res, err)
242		}
243		if res, _ := n.Vote(keys[0].pub, 1, local.BlockID); res.Counted {
244			t.Fatal("duplicate vote must not count")
245		}
246		if _, err := n.Vote(keys[0].pub, 1, alt.BlockID); reason(err) != ReasonAlreadyVoted {
247			t.Fatalf("switch vote got %v, want %s", err, ReasonAlreadyVoted)
248		}
249		rc, _ := n.Candidates(1)
250		for _, c := range rc.Candidates {
251			if c.BlockID == local.BlockID && len(c.Voters) != 1 {
252				t.Fatalf("original vote lost after rejected switch: %d voters", len(c.Voters))
253			}
254			if c.BlockID == alt.BlockID && len(c.Voters) != 0 {
255				t.Fatal("rejected switch must not add vote")
256			}
257		}
258	
259		// 其余三人投竞争候选，第三票使其 >2/3 立即确认。
260		r1, err := n.Vote(keys[1].pub, 1, alt.BlockID)
261		if err != nil || r1.Confirmed {
262			t.Fatalf("alt vote 1: %+v %v", r1, err)
263		}
264		r2, _ := n.Vote(keys[2].pub, 1, alt.BlockID)
265		if r2.Confirmed {
266			t.Fatal("2 votes for alt plus locked local vote: alt has 2, must not confirm yet")
267		}
268		r3, err := n.Vote(keys[3].pub, 1, alt.BlockID)
269		if err != nil || !r3.Confirmed || r3.Block == nil {
270			t.Fatalf("alt should confirm on third vote: %+v %v", r3, err)
271		}
272		if n.CurrentRound() != 2 || n.Height() != 1 {
273			t.Fatalf("round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
274		}
275		// 确认块是竞争候选的标识与顺序。
276		blk, _ := n.BlockAt(1)
277		if blk.ID != alt.BlockID || fmt.Sprint(blk.TxIDs) != fmt.Sprint(list) {
278			t.Fatalf("confirmed block wrong: %+v", blk)
279		}
280		if blk.PreviousID != "" {
281			t.Fatalf("genesis prev = %q, want empty", blk.PreviousID)
282		}
283	
284		// 结果记录：本地候选落选，竞争候选胜出。
285		rc, _ = n.Candidates(1)
286		if !rc.Ended || rc.UnconfirmedEnd {
287			t.Fatalf("round record wrong: %+v", rc)
288		}
289		for _, c := range rc.Candidates {
290			want := CandidateLost
291			if c.BlockID == alt.BlockID {
292				want = CandidateWon
293			}
294			if c.Result != want {
295				t.Fatalf("candidate %s result = %s, want %s", c.BlockID, c.Result, want)
296			}
297		}
298	
299		// 胜出交易均确认一次，账户序号按实际确认结果推进。
300		for _, id := range list {
301			info, _ := n.Tx(id)
302			if info.Status != StatusConfirmed || info.BlockID != alt.BlockID || info.BlockHeight != 1 {
303				t.Fatalf("winner tx %s wrong: %+v", id, info)
304			}
305		}
306		if n.Account(keys[0].pub).ConfirmedSequence != 1 || n.Account(keys[1].pub).ConfirmedSequence != 1 {
307			t.Fatal("confirmed sequences not advanced")
308		}
309		// 确认后旧轮投票一律按轮次拒绝。
310		if _, err := n.Vote(keys[0].pub, 1, local.BlockID); reason(err) != ReasonWrongRound {
311			t.Fatalf("stale vote got %v, want wrong-round", err)
312		}
313	}
