637		}
638		p2, ok := n2.Proposal()
639		if !ok || p2.BlockID != p.BlockID || fmt.Sprint(p2.TxIDs) != fmt.Sprint(p.TxIDs) {
640			t.Fatalf("v1 proposal not restored as local candidate: %+v", p2)
641		}
642		rc, err := n2.Candidates(1)
643		if err != nil {
644			t.Fatal(err)
645		}
646		if !rc.HasRecords || len(rc.Candidates) != 1 || !rc.Candidates[0].Local {
647			t.Fatalf("v1 pending proposal should restore with details: %+v", rc)
648		}
649		if len(rc.Candidates[0].Voters) != 1 {
650			t.Fatal("v1 votes not restored as local candidate votes")
651		}
652		if res, _ := n2.Vote(keys[0].pub, 1, p.BlockID); res.Counted {
653			t.Fatal("restored v1 vote should dedup")
654		}
655		res, _ := n2.Vote(keys[1].pub, 1, p.BlockID)
656		res, _ = n2.Vote(keys[2].pub, 1, p.BlockID)
657		if !res.Confirmed {
658			t.Fatal("v1 node should confirm after reopening")
659		}
