662	// 版本 1 的历史轮次：确认轮与主动结束轮都没有候选详情，确认块本身不变。
663	func TestOpenV1HistoryRounds(t *testing.T) {
664		keys := genKeys(t, 4)
665		dir := t.TempDir()
666		vals := make([][]byte, len(keys))
667		for i, k := range keys {
668			vals[i] = k.pub
669		}
670		n, err := New(dir, Config{Seed: []byte("v1-hist"), Validators: vals, MaxTxsPerBlock: 5})
671		if err != nil {
672			t.Fatal(err)
673		}
674		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
675		n.Submit(a1)
676		p1, _ := n.Propose()
677		confirmCandidate(t, n, keys, p1.BlockID) // 轮次 1 确认，当前轮次 2
678		if _, err := n.EndRound(); err != nil {  // 轮次 2 主动结束，当前轮次 3
679			t.Fatal(err)
680		}
681		block1, _ := n.BlockAt(1)
682	
683		// 改写为版本 1：删除 Rounds。
684		st := n.st.clone()
685		st.Version = 1
686		st.Rounds = nil
687		writeRawState(t, dir, st)
688	
689		n2, err := Open(dir)
690		if err != nil {
691			t.Fatal(err)
692		}
693		if n2.CurrentRound() != 3 || n2.Height() != 1 {
694			t.Fatalf("round=%d height=%d, want 3/1", n2.CurrentRound(), n2.Height())
695		}
696		b, err := n2.BlockAt(1)
697		if err != nil || b.ID != block1.ID {
698			t.Fatalf("confirmed block not preserved: %+v %v", b, err)
699		}
700		rc1, err := n2.Candidates(1)
701		if err != nil {
702			t.Fatal(err)
703		}
704		if rc1.HasRecords || !rc1.Ended || rc1.UnconfirmedEnd || len(rc1.Candidates) != 0 {
705			t.Fatalf("v1 confirmed round should show no records: %+v", rc1)
706		}
707		rc2, err := n2.Candidates(2)
708		if err != nil {
709			t.Fatal(err)
710		}
711		if rc2.HasRecords || !rc2.Ended || !rc2.UnconfirmedEnd {
712			t.Fatalf("v1 ended round should show unconfirmed-end with no records: %+v", rc2)
713		}
714		// 当前轮次尚未提议，查询按未知轮次处理。
715		if _, err := n2.Candidates(3); reason(err) != ReasonUnknownRound {
716			t.Fatalf("current round without proposal got %v, want %s", err, ReasonUnknownRound)
717		}
718		// 迁移后的节点可以继续正常工作。
719		p3, err := n2.Propose()
720		if err != nil || p3.Round != 3 {
721			t.Fatalf("propose after v1 migration: %+v %v", p3, err)
722		}
723	}
724	
725	// 登记失败、投票失败、结束轮次失败时保存错误必须保留操作前状态。
726	func TestCandidateOpsAtomicity(t *testing.T) {
727		keys := genKeys(t, 4)
728		n, dir := newTestNode(t, keys, 10)
729		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
730		n.Submit(a1)
731		local, _ := n.Propose()
732	
733		n.injectSaveErr = errors.New("disk full (simulated)")
734		_, err := n.RegisterCandidate(1, []string{})
735		if err == nil {
736			t.Fatal("register must fail when save fails")
737		}
738		rc, _ := n.Candidates(1)
739		if len(rc.Candidates) != 1 {
740			t.Fatalf("failed register changed state: %d candidates", len(rc.Candidates))
741		}
742		// 投票触发确认时保存失败：轮次不得前进。
743		_, err = n.Vote(keys[0].pub, 1, local.BlockID)
744		if err == nil {
745			t.Fatal("vote must fail when save fails")
746		}
747		if n.CurrentRound() != 1 || n.Height() != 0 {
748			t.Fatalf("failed vote changed state: round=%d height=%d", n.CurrentRound(), n.Height())
749		}
750		// 结束轮次保存失败：轮次不得前进。
751		_, err = n.EndRound()
752		if err == nil {
753			t.Fatal("end round must fail when save fails")
754		}
755		if n.CurrentRound() != 1 {
756			t.Fatalf("failed EndRound changed round: %d", n.CurrentRound())
757		}
758		n.injectSaveErr = nil
759	
760		// 磁盘文件仍是操作前状态。
761		reopened, err := Open(dir)
762		if err != nil {
763			t.Fatal(err)
764		}
765		rc, _ = reopened.Candidates(1)
766		if len(rc.Candidates) != 1 {
767			t.Fatalf("disk state changed despite failed saves: %d candidates", len(rc.Candidates))
768		}
769		if res, err := reopened.Vote(keys[0].pub, 1, local.BlockID); err != nil || !res.Counted {
770			t.Fatalf("vote after reopen: %+v %v", res, err)
771		}
772	}
773	
774	func registerMust(t *testing.T, n *Node, round uint64, ids []string) string {
775		t.Helper()
776		r, err := n.RegisterCandidate(round, ids)
777		if err != nil {
778			t.Fatalf("register %v: %v", ids, err)
779		}
780		return r.BlockID
781	}
782	
783	func confirmCandidate(t *testing.T, n *Node, keys []testKey, blockID string) {
784		t.Helper()
785		round := n.CurrentRound()
786		count := len(keys)*2/3 + 1
787		for i := 0; i < count; i++ {
788			res, err := n.Vote(keys[i].pub, round, blockID)
789			if err != nil {
790				t.Fatalf("vote %d: %v", i, err)
791			}
792			if i == count-1 && !res.Confirmed {
793				t.Fatalf("vote %d should confirm %s", i+1, blockID)
794			}
795		}
796	}
797	
798	func sortStrings(s []string) {
799		for i := 1; i < len(s); i++ {
800			for j := i; j > 0 && s[j-1] > s[j]; j-- {
801				s[j-1], s[j] = s[j], s[j-1]
802			}
803		}
804	}
